<?phpif (!defined('BASEPATH'))    exit('No direct script access allowed');class do_article extends CI_Controller{    var $m_language = '';    var $m_nid_user_login = '';    var $m_nid = '';    var $m_event = '';    var $m_button_click = '';    var $m_link_page = '';    var $m_link_cancel = '';    var $m_form_title = '';    var $m_hidden_image_old = '';    var $m_txt_nid = '';    var $cindex = '';    var $m_txt_ctitle = '';    var $m_txt_cthumb_img = '';    var $m_cbof_nid_lang = '';    var $m_txt_cshort_content = '';    var $m_txt_ccontent = '';    var $m_lang = '';    var $m_arr_new = '';    var $m_chk_alwcmt = '';    var $m_cbo_nid_sec_news_view = '';    var $m_cbo_nid_cat_news_view = '';    var $m_obj_sec_news_view = '';    var $m_obj_cat_news_view = '';    var $m_obj_language = '1';    var $m_nid_news_org = '';    var $m_lang_org = '';    var $m_error_sec = '';    var $m_error_cat = '';    var $m_error_ccontent = '';    var $m_error_ctitle = '';    var $m_error_cshort_content = '';    var $m_link_cancel_trans = '';    var $nid_sec_product = '';    var $cdescription = '';    var $ccode = '';    var $eng_cshort_content = '';    var $eng_ccontent = '';    function __construct()	{		parent::__construct();        session_start();        $this->load->database();        $this->load->helper('ap_db');        $this->load->helper('ap_function');        $this->load->helper('ap_html');        $this->load->helper('ap_view');        $this->load->helper('ap_object');        //$this->load->helper('ap_fck');        $this->tokaban_system_check = '1';        $this->load->model('article_model');        //init_fck();    }    private function m_language_key($str_key)    {        return $this->lang->line('lbl.news.' . $str_key);    }    private function f_set_cookie($cookie_name, $cookie_value)    {        return dbset_cookie('cookie_news_listview_' . $cookie_name, $cookie_value);    }    private function f_get_cookie($cookie_name)    {        return dbget_cookie('cookie_news_listview_' . $cookie_name);    }    function f_edit($nid)    {        $this->m_event = 'edit';        $this->m_nid   = $nid;        $this->do_process();    }    function f_update_edit()    {        $this->m_event = 'update_edit';        $this->do_process();    }    function f_add()    {        $this->m_event = 'add';        $this->m_nid   = '0';        $this->do_process();    }    function f_update_add()    {        $this->m_event = 'update_add';        $this->do_process();    }    function do_process()    {        $this->get_data();        $this->caculate_data();        $this->do_business();        $this->destroy_data();    }    private function get_data()    {        $this->m_nid_user_login = Fget_userdata('session_nid_user');        $this->load->language('ap', 'eng');        if (isset($_FILES["txt_cthumb_img"])) {            $path                   = './upload/image_article/';            $this->m_txt_cthumb_img = Fupload_resize_img($_FILES["txt_cthumb_img"], '../' . $path, 600, 315);        }        if (isset($_POST['txt_ctitle'])) {            $this->m_txt_ctitle = $_POST['txt_ctitle'];//            if (!empty($_POST['chk_alwcmt']))                $this->m_chk_alwcmt = 1;//            $this->m_txt_cshort_content = $_POST['txt_cshort_content'];           //$this->m_txt_ccontent       = $_POST['txt_ccontent'];        }        if (isset($_POST['cbo_nid_sec_news_view']))            $this->m_cbo_nid_sec_news_view = $_POST['cbo_nid_sec_news_view'];        if (isset($_POST['cbo_nid_cat_news_view']))            $this->m_cbo_nid_cat_news_view = $_POST['cbo_nid_cat_news_view'];        if (isset($_POST['nid_sec_product']))            $this->nid_sec_product = $_POST['nid_sec_product'];        if (isset($_POST['ccode']))            $this->ccode = $_POST['ccode'];                    $this->m_cbof_nid_lang = '1';        if (isset($_POST['txt_ctitle_trans'])) {            $this->m_txt_ctitle        = $_POST['txt_ctitle_trans'];            $this->m_cbof_nid_cat_news = $_POST['cbof_nid_cat_news'];            if (!empty($_POST['chk_alwcmt']))                $this->m_chk_alwcmt = 1;            $this->m_txt_cshort_content = $_POST['txt_cshort_content_trans'];            $this->m_txt_ccontent       = $_POST['txt_ccontent_trans'];            $this->cindex               = $_POST['cindex'];        }        if (isset($_POST['hidden_nid']))            $this->m_nid = $_POST['hidden_nid'];        if (isset($_POST['cdescription']))            $this->cdescription = $_POST['cdescription'];        if (isset($_POST['eng_cshort_content']))            $this->eng_cshort_content = $_POST['eng_cshort_content'];        if (isset($_POST['eng_ccontent']))            $this->eng_ccontent = $_POST['eng_ccontent'];        if (isset($_POST['hidden_event']))            $this->m_event = $_POST['hidden_event'];        if (isset($_POST['hidden_button']))            $this->m_button_click = $_POST['hidden_button'];        if (isset($_POST['hidden_image_old']))            $this->m_hidden_image_old = $_POST['hidden_image_old'];        if (isset($_POST['hidden_nid_news_org'])) {            $this->m_nid_news_org = $_POST['hidden_nid_news_org'];        }        if (isset($_POST['hidden_cbof_nid_lang'])) {            $this->m_cbof_nid_lang = $_POST['hidden_cbof_nid_lang'];        }    }    private function caculate_data()    {        $this->m_link_cancel       = base_url() . 'index.php/do_article_listview';        $this->m_link_cancel_trans = base_url() . 'index.php/do_article_listview/f_list_trans/' . $this->f_get_cookie('nid_news_org');        $id_org_news               = $this->f_get_cookie('nid_news_org');        $this->m_obj_cat_news_view = Obj_get_cat_news();        switch ($this->m_event) {            case 'edit':                $this->m_form_title         = $this->m_language_key('FormEditTitle');                $this->m_arr_new            = $this->article_model->get_new_byid($this->m_nid);                $news                       = $this->article_model->get_byid($this->m_nid);                $this->m_txt_cthumb_img     = $news['cimage_thumb'];                $this->m_txt_ctitle         = $news['ctitle'];                $this->cindex               = $news['cindex'];                $this->m_chk_alwcmt         = $news['alwcmt'];                $this->m_txt_cshort_content = $news['cshort_content'];                $this->m_txt_ccontent       = $news['ccontent'];                $this->cdescription           = $news['cdescription'];                $this->eng_cshort_content   = $news['eng_cshort_content'];                $this->eng_ccontent         = $news['eng_ccontent'];                $this->nid_sec_product             = $news['nid_sec_product'];                $this->ccode             = $news['ccode'];                                $this->m_event              = 'update_edit';                break;            case 'add':                $this->m_form_title = $this->m_language_key('FormAddTitle');                $this->m_link_page  = base_url() . 'index.php/do_article/f_update_add';                $this->m_event      = 'update_add';                break;            case 'update_edit':                if ($this->m_button_click == 'btn_submit')                    if ($this->update_data() == TRUE)                        redirect('do_article_listview');                $this->m_form_title = $this->m_language_key('FormEditTitle');                $this->m_link_page  = base_url() . 'index.php/do_article/f_update_edit';                break;            case 'update_add':                $this->m_form_title = $this->m_language_key('FormAddTitle');                if ($this->m_button_click == 'btn_submit')                    if ($this->insert_data() == TRUE)                        redirect('do_article_listview');                break;        }        if ($this->m_nid_news_org == '')            $this->m_nid_news_org = $this->f_get_cookie('nid_news_org');    }    private function do_business()    {        $data['event']                 = $this->m_event;        $data['menu']                  = Fget_menu_html($this->m_nid_user_login);        $data['lbl_form_title']        = $this->m_form_title;        $data['link_page']             = $this->m_link_page;        $data['link_cancel']           = $this->m_link_cancel;        $data['link_cancel_trans']     = $this->m_link_cancel_trans;        $data['btn_update']            = $this->lang->line('btn.0000.Update');        $data['btn_cancel']            = $this->lang->line('btn.0000.Cancel');        $data['fr_img']                = Fstr_replace('admin/', '', base_url());        $data['get_icon_notnull']      = Fget_icon_notnull();        $data['get_message_notnull']   = Fget_icon_notnull() . $this->lang->line('msg.0000.NotNullValue');        $data['lbl_nid']               = $this->m_language_key('nid');        $data['lbl_image']             = $this->m_language_key('image');        $data['lbl_title']             = $this->m_language_key('title');        $data['lbl_cat']               = $this->m_language_key('cat');        $data['lbl_sec']               = $this->m_language_key('sec');        $data['lbl_short_content']     = $this->m_language_key('shortcontent');        $data['lbl_cindex']            = $this->m_language_key('cindex');        $data['lbl_content']           = $this->m_language_key('content');        $data['lbl_status']            = $this->m_language_key('status');        $data['lbl_lang']              = $this->m_language_key('lang');        $data['lbl_first']             = $this->m_language_key('first');        $data['lbl_alwcmt']            = $this->m_language_key('alwcmt');        $data['lbl_choose_sec_news']   = $this->m_language_key('choose_sec_news');        $data['lbl_choose_cat_news']   = $this->m_language_key('choose_cat_news');        $data['nid']                   = $this->m_nid;        $data['menu_active']           = 'article';        $data['cbo_nid_cat_news_view'] = $this->m_cbo_nid_cat_news_view;        $data['txt_ctitle']            = $this->m_txt_ctitle;        if ($this->m_txt_cthumb_img != '')            $data['txt_cthumb_img'] = $this->m_txt_cthumb_img;        else            $data['txt_cthumb_img'] = $this->m_hidden_image_old;        $data['chk_alwcmt']           = $this->m_chk_alwcmt;        $data['txt_cshort_content']   = $this->m_txt_cshort_content;        $data['txt_ccontent']         = $this->m_txt_ccontent;        $data['cindex']               = $this->cindex;        $data['hidden_nid_news_org']  = $this->m_nid_news_org;        $data['hidden_cbof_nid_lang'] = $this->m_cbof_nid_lang;        $data['cdescription']           = $this->cdescription;        $data['eng_cshort_content']   = $this->eng_cshort_content;        $data['eng_ccontent']         = $this->eng_ccontent;        $data['ccode']         = $this->ccode;                $data['nid_sec_product']             = $this->nid_sec_product;        if ($this->m_arr_new > 0) {            $data['lang'] = $this->m_lang;            $data['data'] = $this->m_arr_new;        }        $data['error_ctitle']         = $this->m_error_ctitle;        $data['error_sec']            = $this->m_error_sec;        $data['error_cat']            = $this->m_error_cat;        $data['error_ccontent']       = $this->m_error_ccontent;        $data['error_cshort_content'] = $this->m_error_cshort_content;       // $this->load->library('fckeditor');       // $this->fckeditor->BasePath = base_url() . 'ap_application/plugins/fckeditor/';        //$data['fck2']              = $this->fckeditor->CreateHtml('txt_cshort_content', $this->m_txt_cshort_content, 'Default');        $this->load->view('article_view/index.php', $data);    }    private function destroy_data()    {    }    private function check_valid_not_null()    {        if ($this->m_txt_ctitle == '') {            $this->m_error_ctitle = $this->m_language_key('title') . $this->lang->line('msg.0000.ErorNotNull');            return FALSE;        }                return TRUE;    }    private function check_valid_before_insert()    {        if ($this->check_valid_not_null() == FALSE)            return FALSE;        return TRUE;    }    private function insert_data()    {        if ($this->check_valid_before_insert() == TRUE) {            $data = array(                'ctitle' => $this->m_txt_ctitle,                'ccode' => $this->ccode,                 'nstatus' => 0,                'cimage_thumb' => $this->m_txt_cthumb_img,                'cshort_content' => $this->m_txt_cshort_content,                'cindex' => $this->cindex,                'ccontent' => $this->m_txt_ccontent,                'alwcmt' => $this->m_chk_alwcmt,                'ctype' => 1,                'cdescription' => $this->cdescription,                'eng_cshort_content' => $this->eng_cshort_content,                'eng_ccontent' => $this->eng_ccontent,                'nid_sec_product' => $this->nid_sec_product,                'niduser01' => $this->m_nid_user_login,                'ddate01' => dbget_current_date(),                'niduser02' => $this->m_nid_user_login,                'ddate02' => dbget_current_date()            );            if ($this->m_txt_cthumb_img != '') {                $path                 = '.././upload/image_article/';                $data['cimage_thumb'] = $this->m_txt_cthumb_img;            }            $this->article_model->insert($data);            return TRUE;        } else {            return FALSE;        }    }    private function check_valid_before_update()    {        if ($this->check_valid_not_null() == FALSE)            return FALSE;        return TRUE;    }    private function update_data()    {        if ($this->check_valid_before_update() == true) {            $data = array(                'ctitle' => $this->m_txt_ctitle,                'cindex' => $this->cindex,                'ccode' => $this->ccode,                'cshort_content' => $this->m_txt_cshort_content,                'ccontent' => $this->m_txt_ccontent,                'alwcmt' => $this->m_chk_alwcmt,                'cdescription' => $this->cdescription,                'eng_cshort_content' => $this->eng_cshort_content,                'eng_ccontent' => $this->eng_ccontent,                'nid_sec_product' => $this->nid_sec_product,                'niduser02' => $this->m_nid_user_login,                'ddate02' => dbget_current_date()            );            if ($this->m_txt_cthumb_img != '') {                $path = '.././upload/image_article/';                delfile($path . $this->m_hidden_image_old);                $data['cimage_thumb'] = $this->m_txt_cthumb_img;            }            $this->article_model->update_bynid($this->m_nid, $data);            return TRUE;        } else {            return FALSE;        }    }    function del_img($p_nid)    {        $tmp_news = $this->article_model->get_byid($p_nid);        $img_del  = $tmp_news['cimage_thumb'];        if ($img_del != '') {            $path = '.././upload/image_article/';            delfile($path . $img_del);            $data = array(                'cimage_thumb' => ''            );        }        $this->article_model->update_bynid($p_nid, $data);    }}